parameters.query:
DELETE FROM mensajes 
WHERE conversacion_id IN (
    SELECT c.id FROM conversaciones c
    JOIN clientes cl ON cl.id = c.cliente_id
    WHERE cl.wa_id = $1
);

UPDATE conversaciones 
SET estado = 'cerrada', ultimo_mensaje_en = CURRENT_TIMESTAMP 
WHERE cliente_id IN (
    SELECT id FROM clientes WHERE wa_id = $1
);

UPDATE clientes 
SET nombre = 'Cliente' 
WHERE wa_id = $1;

SELECT 'ok' AS status;

